import {PGlite} from '@electric-sql/pglite';
import {readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {randomUUID} from 'node:crypto';
import assert from 'node:assert/strict';
const db=new PGlite(),here=new URL('./',import.meta.url),passed=[];
const q=(sql,args=[])=>db.query(sql,args),v=async(sql,args=[])=>(await q(sql,args)).rows[0]?.v;
const check=async(name,fn)=>{await fn();passed.push(name);console.log('PASS '+name)};
async function account(verified=true,anonymous=false){const id=randomUUID();await q('insert into auth.users(id,email,email_confirmed_at,is_anonymous) values($1,$2,$3,$4)',[id,id+'@example.test',verified?new Date():null,anonymous]);return id;}
async function call(id,sql,args=[],role='authenticated'){await q("select set_config('request.jwt.claims',$1,false)",[JSON.stringify({sub:id,amr:[{method:'otp',timestamp:Math.floor(Date.now()/1000)}]})]);await db.exec('set role '+role);try{return await v(sql,args)}finally{await db.exec('reset role')}}
const create=(id,request,name='Synthetic Group',more=false,hc=11.2)=>call(id,`select public.${more?'iig_create_additional_playing_group':'iig_create_owned_playing_group'}($1,$2,$3,$4) v`,[name,'Alex Test',hc,request]);
const owned=(id,pin)=>call(id,'select public.iig_read_owned_entry_group($1) v',[pin]);
const snapshot=()=>v("select jsonb_build_object('groups',(select jsonb_agg(to_jsonb(g) order by id) from public.tens_in_groups g),'owners',(select jsonb_agg(to_jsonb(g) order by group_id) from iig_private.group_owners g),'members',(select jsonb_agg(to_jsonb(g) order by group_id,user_id) from iig_private.group_members g),'settings',(select jsonb_agg(to_jsonb(g) order by group_pin) from public.iig_notification_settings g),'events',(select jsonb_agg(to_jsonb(g) order by id) from public.iig_notification_events g)) v");
try{
await db.exec(readFileSync(new URL('fixture.sql',here),'utf8'));
const alice=await account(),bob=await account(),firstRequest=randomUUID();
const first=await create(alice,firstRequest,'Saturday Golf');
const before=await snapshot();
await db.exec(readFileSync(new URL('../supabase/migrations/'+readdirSync(new URL('../supabase/migrations',here))[0],here),'utf8'));
await check('migration preserves existing groups, memberships and payment metadata',async()=>assert.deepEqual(await snapshot(),before));
await check('single-group legacy sign-in and original retry remain compatible',async()=>{assert.equal((await call(alice,'select public.iig_read_entry_group() v')).group_pin,first.group_pin);assert.deepEqual(await create(alice,firstRequest,'Saturday Golf'),first);});
let second;const extraRequest=randomUUID(),firstState=await owned(alice,first.group_pin);
await check('same organiser creates a second group with its own linked player',async()=>{second=await create(alice,extraRequest,'Wednesday Golf',true);assert.notEqual(second.group_pin,first.group_pin);assert.notEqual(second.player_id,first.player_id);const g=await owned(alice,second.group_pin);assert.equal(g.state.players.length,1);assert.equal(g.state.players[0].id,second.player_id);assert.equal(g.state.players[0].paid,false);assert.equal(g.state.players[0].playingThisRound,false);assert.equal(g.state.players[0].stableford,null);assert.deepEqual(await owned(alice,first.group_pin),firstState);});
await check('additional creation retries cannot create duplicate groups or players',async()=>{const before=await snapshot();assert.deepEqual(await create(alice,extraRequest,'Wednesday Golf',true),second);await assert.rejects(()=>create(alice,extraRequest,'Changed name',true),/already has a group/);assert.deepEqual(await snapshot(),before);});
const third=await create(bob,randomUUID(),'Other Organiser');
await check('group list contains only the signed-in organiser’s group summaries',async()=>{const a=await call(alice,'select public.iig_list_owned_groups() v');assert.deepEqual(a.map(g=>g.group_name),['Saturday Golf','Wednesday Golf']);assert.deepEqual(Object.keys(a[0]).sort(),['group_name','group_pin','retired','status']);assert.deepEqual((await call(bob,'select public.iig_list_owned_groups() v')).map(g=>g.group_pin),[third.group_pin]);});
await check('explicit owner reads remain pinned to the requested group',async()=>{assert.equal((await owned(alice,second.group_pin)).state.groupName,'Wednesday Golf');assert.equal((await owned(alice,first.group_pin)).state.groupName,'Saturday Golf');for(const pin of [null,'00000','not-a-pin'])await assert.rejects(()=>owned(alice,pin),/Choose a group/);await assert.rejects(()=>owned(alice,third.group_pin),/Organiser access required/);});
await check('legacy ambiguous reads fail instead of opening the wrong group',async()=>{for(const fn of ['iig_read_entry_group','iig_get_owned_group','iig_my_group_identity'])await assert.rejects(()=>call(alice,'select public.'+fn+'() v'),/Choose a group/);assert.equal((await call(bob,'select public.iig_my_group_identity() v')).group_pin,third.group_pin);});
await check('legacy creation remains protected while its original retry still works',async()=>{const before=await snapshot();await assert.rejects(()=>create(alice,randomUUID(),'Accidental group'),/already has a group/);assert.deepEqual(await create(alice,firstRequest,'Saturday Golf'),first);assert.deepEqual(await snapshot(),before);});
await check('player reads and membership cannot grant organiser access',async()=>{await call(bob,'select public.iig_join_release_group($1,$2,$3,$4) v',[first.group_pin,firstState.invite_token,'Bob Player',9]);assert.ok((await call(bob,'select public.iig_read_entry_group($1) v',[first.group_pin])).player_id);await assert.rejects(()=>owned(bob,first.group_pin),/Organiser access required/);});
await check('settings save changes only the selected owned group',async()=>{const firstBefore=await owned(alice,first.group_pin),g=await owned(alice,second.group_pin);const state={...g.state,paymentProvider:'monzo',paymentLink:'https://monzo.me/synthetic-organiser'};await call(alice,'select public.iig_operate_owned_group($1,$2,$3,$4) v',[second.group_pin,'settings',state,g.revision]);assert.equal((await owned(alice,second.group_pin)).state.paymentLink,state.paymentLink);assert.deepEqual(await owned(alice,first.group_pin),firstBefore);});
await check('another organiser cannot write settings even when joined as a player',async()=>{const before=await snapshot(),g=await owned(alice,first.group_pin);await assert.rejects(()=>call(bob,'select public.iig_operate_owned_group($1,$2,$3,$4) v',[first.group_pin,'settings',g.state,g.revision]),/Organiser access required|owner|OWNER/i);assert.deepEqual(await snapshot(),before);});
await check('stale revision cannot overwrite either group',async()=>{const before=await snapshot(),g=await owned(alice,second.group_pin);await assert.rejects(()=>call(alice,'select public.iig_operate_owned_group($1,$2,$3,$4) v',[second.group_pin,'settings',g.state,g.revision-1]),/reload|revision|changed/i);assert.deepEqual(await snapshot(),before);});
await check('invalid handicap or failed membership rolls back additional creation',async()=>{const before=await snapshot();for(const hc of [null,-10.1,60.1,11.22,'NaN'])await assert.rejects(()=>create(alice,randomUUID(),'Invalid',true,hc),/Enter your handicap/);await db.exec("CREATE FUNCTION public.synthetic_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Synthetic failure'; END $$; CREATE TRIGGER synthetic_fail BEFORE INSERT ON iig_private.group_members FOR EACH ROW EXECUTE FUNCTION public.synthetic_fail();");try{await assert.rejects(()=>create(alice,randomUUID(),'Failed Group',true),/Synthetic failure/)}finally{await db.exec('DROP TRIGGER synthetic_fail ON iig_private.group_members; DROP FUNCTION public.synthetic_fail();')}assert.deepEqual(await snapshot(),before);});
await check('anonymous, unverified and anonymous-user accounts cannot use new RPCs',async()=>{for(const id of [await account(false),await account(true,true)]){await assert.rejects(()=>call(id,'select public.iig_list_owned_groups() v'),/Verified organiser/);await assert.rejects(()=>create(id,randomUUID(),'Denied',true),/Verified organiser/);}await assert.rejects(()=>call(null,'select public.iig_list_owned_groups() v',[],'anon'),/permission denied/);});
await check('private schema stays closed and public RPC grants are restricted',async()=>{assert.equal(await v("select has_schema_privilege('authenticated','iig_private','USAGE') v"),false);for(const sig of ['public.iig_list_owned_groups()','public.iig_read_owned_entry_group(text)','public.iig_create_additional_playing_group(text,text,numeric,uuid)']){const flags=await v("select jsonb_build_object('anon',has_function_privilege('anon',oid,'EXECUTE'),'auth',has_function_privilege('authenticated',oid,'EXECUTE'),'service',has_function_privilege('service_role',oid,'EXECUTE'),'settings',proconfig) v from pg_proc where oid=$1::regprocedure",[sig]);assert.equal(flags.anon,false);assert.equal(flags.auth,true);assert.equal(flags.service,false);assert.deepEqual(flags.settings,['search_path=pg_catalog']);}});
await check('additional creation requires an existing organiser group',async()=>{const fresh=await account();await assert.rejects(()=>create(fresh,randomUUID(),'Extra without first',true),/Create your first group/);assert.deepEqual(await call(fresh,'select public.iig_list_owned_groups() v'),[]);});
await check('account departure covers every owned group and preserves golf records',async()=>{const a=await owned(alice,first.group_pin),b=await owned(alice,second.group_pin),other=await owned(bob,third.group_pin);assert.equal(await call(alice,'select public.iig_prepare_account_deletion() v'),true);await assert.rejects(()=>call(alice,'select public.iig_list_owned_groups() v'),/Verified organiser/);for(const g of [a,b])assert.deepEqual(await v('select state v from public.tens_in_groups where group_pin=$1',[g.group_pin]),g.state);assert.deepEqual(await owned(bob,third.group_pin),other);assert.equal(Number(await v('select count(*) v from iig_private.release_groups where owner_departed_at is not null')),2);});
writeFileSync(new URL('database-results.json',here),JSON.stringify({passed:passed.length,checks:passed,productionChanged:false,syntheticDataOnly:true},null,2)+'\n');console.log(JSON.stringify({passed:passed.length}));
}catch(e){console.error(JSON.stringify({error:e.message,code:e.code,detail:e.detail,where:e.where}));process.exitCode=1;}finally{await db.close();}
